      <v-icon size="16">mdi-arrow-left</v-icon>
      ブログ一覧に戻る
    </button>
  </div>
</template>

<script>
import { blogPosts } from "@/constants/blogPosts";
import exshipsLogo from "@/assets/exshipsLogo.png";

export default {
  name: "BlogDetailView",
  data: () => ({
    exshipsLogo,
    pageVisible: false,
    post: null,
  }),
  mounted() {
    const id = this.$route.params.id;
    this.post = blogPosts.find((p) => p.id === id) || null;
    if (this.post) {
      document.title = `${this.post.title} | 合同会社エクスシップス`;
    }
    setTimeout(() => (this.pageVisible = true), 100);
  },
};
</script>

